-- handler

function CompeteTaskRewardsDialog:OnClickCloseButtonHandler_()
    UIModule.CloseDialog(self.controller)
end


function CompeteTaskRewardsDialog:OnUpdateTaskListCellHandler_(listView, listIndex)
    if listIndex < 0 then return end
    local cell = listView:NewListViewItem("Cell")
    ---@type LadderCompetionTaskRewardCellNode
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, CompeteTaskRewardCellNode)
    if nodeEnv then
        local luaIndex = listIndex + 1
        local cellData = checkTable( self.taskArray[luaIndex])
        -- init cell
        nodeEnv:SetLuaIndex(luaIndex)
        nodeEnv:SetCellData(cellData)
        nodeEnv:SetClickCB(Bind(self, self.OnClickTaskListCellCallback_))
        -- init anim
        if self.itemShowNum_ == nil then
            local cellSizeH   = cell.CachedRectTransform.rect.height + cell.Padding
            self.itemShowNum_ = math.ceil(self.TaskListView.ViewPortHeight / cellSizeH)
        end
        if not self.cellAnimMap_[luaIndex] and listIndex <= self.itemShowNum_ then
            self.cellAnimMap_[luaIndex] = true
            nodeEnv:PlayAnimByEnter(listIndex)
        else
            nodeEnv:PlayAnimByShowed()
        end
    end
    return cell
end


function CompeteTaskRewardsDialog:DrawRewards(taskId)
    GameUtils.Request(Interfaces.ActivityUserPkDrawTask, { activityUuid = self.comp:GetActivityUuid(), taskId = taskId },
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    -- draw rewards
                    local rewardList = checkTable(response.data.rewards)
                    GoodsUtils.DrawRewards(rewardList, true)
                    UIModule.OpenDialog(UIArgs(Constants.UITypeIds.UICommonRewardPop, { rewards = rewardList }))
                    local drawIndexs = {}
                    -- id 存在 单个领取
                    if taskId then
                        taskId = checkInt(taskId)
                        for i, v in pairs(self.taskArray) do
                            if checkInt(v.taskId) == taskId then
                                drawIndexs[tostring(i)] = true
                                self.comp:SetTaskInfoStatusById(taskId , Constants.GetStatus.Has)
                                break
                            end
                        end
                    else
                        for i, v in pairs(self.taskArray) do
                            if checkInt(v.status) == Constants.GetStatus.Can then
                                drawIndexs[tostring(i)] = true
                                self.comp:SetTaskInfoStatusById(v.taskId , Constants.GetStatus.Has)
                            end
                        end
                    end
                    for itemCount = 1, self.TaskListView.ShownItemCount do
                        local cellNode = self.TaskListView:GetShownItemByIndex(itemCount - 1)
                        if not isNull(cellNode) then
                            ---@type CompeteTaskRewardCellNode
                            local nodeEnv = CfUtils.GetLuaScr(cellNode, CompeteTaskRewardCellNode)
                            if nodeEnv then
                                local cellLuaIndex = nodeEnv:GetLuaIndex()
                                if drawIndexs[tostring(cellLuaIndex)] then
                                    nodeEnv:SetCellData(self.taskArray[cellLuaIndex])
                                    if taskId then
                                        break
                                    end
                                end
                            end
                        end
                    end
                    -- refresh red point
                    self:RefreshRedPointState_()
                end
            end
    )
end

function CompeteTaskRewardsDialog:AllDrawRewardsClick()
    local isHaveDraw = false
    local ladderTaskList = checkTable(self.taskArray)
    for _, listData in ipairs(ladderTaskList) do
        if checkInt(listData.status) == Constants.GetStatus.Can then
            isHaveDraw = true
            break
        end
    end
    if not isHaveDraw then
        GameUtils.Toast(localize("暂无奖励可领取"))
        return
    end
    self:DrawRewards()
end

function CompeteTaskRewardsDialog:OnClickTaskListCellCallback_(luaIndex)
    local cellData = checkTable(self.taskArray[luaIndex])
    local statusId = checkInt(self.comp:GetTaskInfoStatusById(cellData.taskId))
    if statusId == Constants.GetStatus.Not then
        GameUtils.Toast(localize('不能领取'))
        return
    end
    if statusId == Constants.GetStatus.Has then
        GameUtils.Toast(localize('已领取'))
        return
    end
    self:DrawRewards(cellData.taskId)
end


return CompeteTaskRewardsDialog
